import cn from 'classnames';
import { ImageProps } from './image.types';
import './image.scss';

export function Image({
  uuid,
  id,
  srcset,
  target,
  alt,
  ratio,
  imageLink,
  title,
  lazyEnabled,
  className,
  useCaption,
  dataLayer,
  ...rest
}: ImageProps) {
  const imageRatioType = cn({
    'image--16-9': ratio === '16:9',
    'image--4-3': ratio === '4:3',
    'image--1-1': ratio === '1:1',
    'image--21-9': ratio === '21:9',
  });

  const loading = lazyEnabled ? 'lazy' : undefined;

  return (
    <div className={cn('image', imageRatioType, className)}>
      <div data-asset-id={uuid} id={id} data-cmp-data-layer="" className="cmp-image">
        {imageLink ? (
          <a className="cmp-image__link" data-cmp-clickable="" href={imageLink.url} target={target}>
            <img alt={alt} srcSet={srcset} loading={loading} {...rest} />
          </a>
        ) : (
          <img alt={alt} srcSet={srcset} loading={loading} {...rest} />
        )}
        {useCaption && (
          <span className="cmp-image__title" itemProp={title}>
            {alt}
          </span>
        )}
        {!useCaption && <meta itemProp="caption" content={title} />}
      </div>
    </div>
  );
}

export default Image;
